/*
 * Valida el horario operativo y filtra líneas que aún tienen cupo hoy.
 *
 * Retorna UN solo item con { lines, count } para garantizar que el
 * siguiente HTTP node (GET contacts) se ejecute exactamente 1 vez,
 * sin importar cuántas líneas activas haya.
 */
const lines = $input.all().map(i => i.json);

// Horario operativo: 9AM-22PM hora Argentina (UTC-3)
const nowArg = new Date(
  new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' })
);
const hour = nowArg.getHours();

if (hour < 9 || hour >= 22) {
  return [{ json: { lines: [], count: 0, reason: `Fuera de horario operativo: ${hour}hs ARG` } }];
}

const available = lines.filter(line => {
  if (!line.phone_number || !line.instance_name) return false;
  return (line.daily_limit || 0) - (line.messages_sent_today || 0) > 0;
});

return [{
  json: {
    lines:      available,
    count:      available.length,
    checked_at: new Date().toISOString(),
    hour_arg:   hour
  }
}];

/*
 * Construye un job por cada línea activa asignando:
 *   - Contacto receptor (round-robin sobre el pool cargado)
 *   - Mensaje aleatorio según número de fase (config en warmup_phases)
 *   - Delay calculado con jitter ±10% sobre el rango de la fase
 *
 * Devuelve N items — Execute Workflow los dispara como sub-ejecuciones
 * asíncronas e independientes (una por línea, en paralelo controlado).
 *
 * Concurrencia: el sub-workflow WF-010a tiene maxConcurrency=8 (configurable
 * en Settings del workflow en n8n). Jobs que excedan ese límite se encolan.
 */
const { lines } = $('Code – Validate & Consolidate').first().json;
const contacts  = $input.all().map(i => i.json).filter(c => c.phone_number);

if (!contacts.length) return [];

// ── Banco de mensajes por fase (sincronizado con warmup_phases tabla) ─────
const MESSAGES = {
  1: [ // Fase 1 (días 1-3): texto puro, natural y corto
    'Hola! cómo andás?','Buenas! todo bien?','Ey! qué tal?',
    'Hola, cómo estás?','Buenas! qué hacés?','Hola! cómo va todo?',
    'Ey, qué onda?','Hola, todo bien por allá?','Buenas! cómo te va?',
    'Hola! cómo va el día?'
  ],
  2: [ // Fase 2 (días 4-7): emojis simples
    'Hola! cómo andás? 😊','Buenas! todo bien? 👋','Ey qué tal! 🙌',
    'Hola, cómo estás? 😄','Buenas! qué hacés? ☀️','Hola! cómo va todo? 👍',
    'Qué onda! todo bien? 🎉','Hola por acá! cómo te va? 😁',
    'Buenas! se viene el finde 🙌','Ey! apareció el sol por allá? ☀️',
    'Hola! tomando unos mates ☕ y vos?','Qué tal el día hoy? 😊',
    'Buenas! qué está pasando por allá? 👀','Ey! hace rato no hablamos 😊'
  ],
  3: [ // Fase 3 (días 8-14): conversaciones cortas
    'Hola! cómo andás? 😊 Hoy está haciendo un calor terrible por acá',
    'Buenas! todo bien? 👋 Recién salí del trabajo, qué tal el día?',
    'Ey qué tal! 🙌 Che, tenés alguna serie para recomendar?',
    'Hola! 😄 Estoy tomando unos mates, nada mejor para la tarde',
    'Buenas! ☀️ Qué semana larga, ya tengo ganas del finde',
    'Hola! 👍 Pasé por el centro hoy y estaba lleno de gente, un caos',
    'Qué onda! 🎉 Viste el partido de anoche? qué partidazo',
    'Hola! 😁 El fin de semana estuve en el campo, una paz total',
    'Buenas! 🙌 Me anoté al gimnasio otra vez, a ver si me mantengo jaja',
    'Ey! ☀️ Hoy hice compras y no podía creer los precios, todo carísimo'
  ],
  4: [ // Fase 4 (día 15+): mensajes ricos y contextuales
    'Hola! cómo andás? 😊 Hoy está haciendo un calor terrible, qué tal el clima donde estás?',
    'Buenas! 👋 Recién salí del trabajo y vine caminando, qué semana larga',
    'Ey! 🙌 Che, ¿viste el partido de anoche? no esperaba ese resultado para nada',
    'Hola! 😄 Estoy tomando unos mates con galletitas, lo más. Vos qué hacés?',
    'Buenas tardes! ☀️ Se viene el finde, algún plan? Nosotros vamos al campo',
    'Hola! 👍 Pasé por el centro y estaba todo cortado, tardé el doble de siempre',
    'Qué onda! 🎉 Me enteré que abrieron una pizzería nueva acá cerca, hay que ir a probar',
    'Hola! 😁 El fin de semana hice asado, quedó buenísimo. Vos qué hiciste?'
  ]
};

const pickRandom = arr => arr[Math.floor(Math.random() * arr.length)];

// Delay con jitter ±10% sobre el rango de la fase
const calcDelay = (min, max) => {
  const base   = Math.floor(Math.random() * (max - min + 1)) + min;
  const jitter = Math.round(base * 0.10 * (Math.random() * 2 - 1));
  return Math.max(5, base + jitter);
};

return lines.map((line, idx) => ({
  json: {
    warmup_number_id:  line.id,
    phone_number:      line.phone_number,
    instance_name:     line.instance_name,
    current_day:       line.current_day,
    contact_id:        contacts[idx % contacts.length].id,
    recipient_phone:   contacts[idx % contacts.length].phone_number,
    message_text:      pickRandom(MESSAGES[line.phase_number || 1] || MESSAGES[1]),
    message_type:      line.message_type,
    // delay_sec es el valor base — el sub-workflow lo recalcula con el health score
    delay_sec:         calcDelay(line.min_delay_seconds, line.max_delay_seconds),
    daily_limit:       line.daily_limit,
    remaining_today:   line.daily_limit - (line.messages_sent_today || 0),
    // Parámetros de fase necesarios para el override adaptativo en WF-010a
    phase_number:      line.phase_number || 1,
    phase_min_delay:   line.min_delay_seconds,
    phase_max_delay:   line.max_delay_seconds,
    phase_daily_limit: line.daily_limit
  }
}));

/*
 * Resumen del ciclo de despacho — corre UNA vez para todos los items.
 * Como el sub-workflow corre en modo async, solo podemos reportar
 * cuántos jobs fueron despachados, no sus resultados individuales.
 * Los resultados detallados están en warmup_activity_log (Supabase).
 */
const dispatched = $input.all();
const count      = dispatched.length;

const instanceNames = [...new Set(dispatched.map(i => i.json.instance_name || '?'))];

const summary = {
  dispatched_count: count,
  instances:        instanceNames,
  dispatched_at:    new Date().toISOString(),
  cycle:            'every-15min'
};

console.log(`[WF-010] Despacho completado: ${count} jobs | ${instanceNames.join(', ')}`);

return [{ json: summary }];
